// Собирает итоговый документ Word. Содержание собирается в два прохода: сначала документ
// с заглушками, LibreOffice делает PDF, по нему находятся страницы разделов,
// затем документ собирается заново с настоящими номерами страниц.
// Запуск: node build-docx.mjs (после node render.mjs)
import { createRequire } from 'node:module';
import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
