const {
  Document, Packer, Paragraph, TextRun, ImageRun, Table, TableRow, TableCell, Footer,
  AlignmentType, PageOrientation, WidthType, ShadingType, BorderStyle, VerticalAlign,
  LevelFormat, PageNumber, TabStopType, TableLayoutType, LineRuleType,
} = require('docx');

const OUT_NAME = 'Багишев_Алихан_Ахадович_НеваИмпорт_Импортная_закупка';
const IMG = join(here, 'build', 'img');
const D = JSON.parse(readFileSync(join(here, 'data.json'), 'utf8'));

// ---------- расчёты по данным модели ----------
const r1 = (v) => Math.round(v * 10) / 10;
const sum = (a) => r1(a.reduce((s, [, v]) => s + v, 0));
const NB = ' ';
const fmt = (v, d = 1) => {
  const x = Math.round(v * 10 ** d) / 10 ** d;
  const s = Number.isInteger(x) ? String(x) : x.toFixed(d).replace(/0+$/, '');
  return s.replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, NB);
};
const st = D.stages.map((s) => ({ ...s, a: sum(s.asis), t: sum(s.tobe) }));
const T = {
  asis: r1(st.reduce((s, x) => s + x.a, 0)),
  tobe: r1(st.reduce((s, x) => s + x.t, 0)),
  fixed: r1(st.filter((x) => D.fixedStages.includes(x.n)).reduce((s, x) => s + x.a, 0)),
  hA: r1(st.reduce((s, x) => s + x.hAsis, 0) * 100) / 100,
  hT: Math.round(st.reduce((s, x) => s + x.hTobe, 0) * 100) / 100,
};
T.mA = r1(T.asis - T.fixed); T.mT = r1(T.tobe - T.fixed);
T.cut = r1(T.asis - T.tobe); T.cutPct = r1((T.cut / T.asis) * 100);
T.mCutPct = r1(((T.mA - T.mT) / T.mA) * 100);
T.hCutPct = r1(((T.hA - T.hT) / T.hA) * 100);
T.yearA = Math.round(T.hA * D.shipmentsPerYear); T.yearT = Math.round(T.hT * D.shipmentsPerYear);
T.fte = r1((T.yearA - T.yearT) / D.hoursPerFte);
T.ratio = r1(T.hA / T.hT);
T.pipe = r1((T.tobe / T.asis) * 100);
T.safety = r1(Math.sqrt(T.tobe / T.asis) * 100);
const S = (n) => st.find((x) => x.n === n);
T.noBlCut = r1(T.cut - (S(6).a - S(6).t));
console.log('Расчёт:', T);

// ---------- оформление ----------
const FONT = 'Times New Roman';
const PT = (p) => p * 2;
const MM = (mm) => Math.round((mm / 25.4) * 1440);
const PORTRAIT = { width: 11906, height: 16838 };
const MARGIN_P = { top: MM(20), bottom: MM(20), left: MM(30), right: MM(15), header: MM(10), footer: MM(10) };
const MARGIN_L = { top: MM(20), bottom: MM(18), left: MM(20), right: MM(15), header: MM(10), footer: MM(8) };
const TW_P = PORTRAIT.width - MARGIN_P.left - MARGIN_P.right; // ширина текста, книжная
const TW_L = PORTRAIT.height - MARGIN_L.left - MARGIN_L.right; // ширина текста, альбомная
const INDENT = 709;

// Текст набирается так, как его набирают в Word: без длинного тире, стрелок
// и значков ≈ ≤, буква «е» вместо «ё». Если такой знак попал в текст, сборка падает.
const clean = (t) => {
  const s = String(t).replace(/ё/g, 'е').replace(/Ё/g, 'Е');
  const bad = s.match(/[\u2014\u2192\u2248\u2264\u2265\u2212]/);
  if (bad) throw new Error(`Знак «${bad[0]}» в тексте: ${s.slice(0, 120)}`);
  return s;
};

// **жирный** внутри строки
function runs(text, o = {}) {
  const parts = clean(text).split(/(\*\*[^*]+\*\*)/g).filter(Boolean);
  return parts.map((p) => p.startsWith('**')
    ? new TextRun({ text: p.slice(2, -2), bold: true, size: o.size, italics: o.italics, font: FONT })
    : new TextRun({ text: p, bold: o.bold, size: o.size, italics: o.italics, font: FONT }));
}
const P = (text, o = {}) => new Paragraph({
  children: runs(text, o),
  alignment: o.align || AlignmentType.JUSTIFIED,
  indent: o.noIndent ? undefined : { firstLine: INDENT },
  spacing: { line: 360, before: o.before || 0, after: o.after || 0, lineRule: LineRuleType.AUTO },
  keepNext: o.keepNext, keepLines: o.keepLines, pageBreakBefore: o.pageBreak,
});
const H1 = (text, o = {}) => new Paragraph({
  children: [new TextRun({ text: clean(text), bold: true, size: PT(14), font: FONT })],
  style: 'Heading1', pageBreakBefore: !!o.pageBreak,
  alignment: o.center ? AlignmentType.CENTER : AlignmentType.LEFT,
  indent: o.center ? undefined : { firstLine: INDENT },
  spacing: { before: o.pageBreak ? 0 : 360, after: 240, line: 360, lineRule: LineRuleType.AUTO }, keepNext: true,
});
const H2 = (text) => new Paragraph({
  children: [new TextRun({ text: clean(text), bold: true, size: PT(14), font: FONT })],
  style: 'Heading2', indent: { firstLine: INDENT }, spacing: { before: 240, after: 120, line: 360, lineRule: LineRuleType.AUTO }, keepNext: true,
});
const bullet = (text, o = {}) => new Paragraph({
  children: runs(text), numbering: { reference: 'dash', level: 0 },
  alignment: AlignmentType.JUSTIFIED, spacing: { line: 360, lineRule: LineRuleType.AUTO }, keepNext: o.keepNext,
});
let listInstance = 0;
const numbered = (items, o = {}) => {
  listInstance += 1;
  return items.map((t) => new Paragraph({
    children: runs(t), numbering: { reference: o.ref || 'num', level: 0, instance: listInstance },
    alignment: o.align || AlignmentType.JUSTIFIED, spacing: { line: 360, lineRule: LineRuleType.AUTO },
  }));
};

// ---------- рисунки ----------
const pxPerMm = 96 / 25.4;
function figure(name, widthMm, caption, o = {}) {
  const meta = JSON.parse(readFileSync(join(IMG, `${name}.json`), 'utf8'));
  let w = widthMm * pxPerMm, h = (w * meta.h) / meta.w;
  if (o.maxHmm && h > o.maxHmm * pxPerMm) { h = o.maxHmm * pxPerMm; w = (h * meta.w) / meta.h; }
  return [
    new Paragraph({
      children: [new ImageRun({ type: 'png', data: readFileSync(join(IMG, `${name}.png`)), transformation: { width: Math.round(w), height: Math.round(h) }, altText: { title: caption, description: caption, name } })],
      alignment: AlignmentType.CENTER, keepNext: true, spacing: { before: o.before ?? 120, after: 60, line: 240, lineRule: LineRuleType.AUTO },
    }),
    new Paragraph({
      children: [new TextRun({ text: clean(caption), size: PT(o.capSize || 14), font: FONT })],
      alignment: AlignmentType.CENTER, spacing: { after: o.after ?? 200, line: 276, lineRule: LineRuleType.AUTO },
    }),
  ];
}

// ---------- таблицы ----------
const B = { style: BorderStyle.SINGLE, size: 4, color: '000000' };
const BORDERS = { top: B, bottom: B, left: B, right: B, insideHorizontal: B, insideVertical: B };
function cellParas(v, o) {
  const lines = Array.isArray(v) ? v : [v];
  return lines.map((t) => new Paragraph({
    children: runs(String(t), { size: o.size, bold: o.bold }),
    alignment: o.align || AlignmentType.LEFT, spacing: { line: 240, before: 0, after: 0, lineRule: LineRuleType.AUTO },
  }));
}
function table(caption, head, rows, widthsMm, o = {}) {
  const total = o.width || TW_P;
  const sumMm = widthsMm.reduce((a, b) => a + b, 0);
  const cols = widthsMm.map((w) => Math.floor((w / sumMm) * total));
  cols[cols.length - 1] += total - cols.reduce((a, b) => a + b, 0);
  const size = PT(o.font || 12);
  const align = o.align || [];
  const mk = (cells, isHead, shade) => new TableRow({
    tableHeader: isHead, cantSplit: true,
    children: cells.map((v, i) => new TableCell({
      width: { size: cols[i], type: WidthType.DXA },
      margins: { top: 40, bottom: 40, left: 80, right: 80 },
      verticalAlign: isHead ? VerticalAlign.CENTER : VerticalAlign.TOP,
      shading: isHead ? { fill: 'E6EAEE', type: ShadingType.CLEAR, color: 'auto' } : shade ? { fill: 'F4F6F8', type: ShadingType.CLEAR, color: 'auto' } : undefined,
      children: cellParas(v, { size, bold: isHead, align: isHead ? AlignmentType.CENTER : align[i] }),
    })),
  });
  const out = [];
  out.push(new Paragraph({
    children: [new TextRun({ text: clean(caption), size: PT(14), font: FONT })],
    alignment: AlignmentType.LEFT, keepNext: true, spacing: { before: 200, after: 80, line: 276, lineRule: LineRuleType.AUTO },
  }));
  out.push(new Table({
    width: { size: total, type: WidthType.DXA }, columnWidths: cols, layout: TableLayoutType.FIXED, borders: BORDERS,
    rows: [mk(head, true), ...rows.map((r) => mk(r.cells || r, false, r.shade))],
  }));
  out.push(new Paragraph({ children: [], spacing: { after: 120, line: 240, lineRule: LineRuleType.AUTO } }));
  return out;
}
const C = AlignmentType.CENTER;

