function tocBlock(pages) {
  const out = [new Paragraph({
    children: [new TextRun({ text: 'СОДЕРЖАНИЕ', bold: true, size: PT(14), font: FONT })],
    alignment: AlignmentType.CENTER, spacing: { after: 240, line: 360, lineRule: LineRuleType.AUTO }, pageBreakBefore: true,
  })];
  for (const [title] of TOC) {
    out.push(new Paragraph({
      tabStops: [{ type: TabStopType.RIGHT, position: TW_P, leader: 'dot' }],
      indent: { left: 0 },
      spacing: { line: 360, lineRule: LineRuleType.AUTO },
      children: [new TextRun({ text: clean(title), size: PT(14), font: FONT }), new TextRun({ text: `\t${pages[title] ?? '00'}`, size: PT(14), font: FONT })],
    }));
  }
  return out;
}

